  segs(str) {
    return String(str).split(/(\*\*[^*]+\*\*|`[^`]+`|\[\^\d+\])/).filter((x) => x !== '').map((x) => {
      if (x.startsWith('**') && x.endsWith('**')) return { b: true, text: x.slice(2, -2) };
      if (x.startsWith('`') && x.endsWith('`')) return { c: true, text: x.slice(1, -1) };
      const m = x.match(/^\[\^(\d+)\]$/);
      if (m) return { f: true, n: m[1] };
      return { t: true, text: x };
    });
  }
